select pg_temp.afirma(public.nano_lifecycle_liberar_item('ed000000-0000-0000-0000-000000000001',(select id from public.pipeline_itens where loja_id='ed000000-0000-0000-0000-000000000001' and entrada->>'origem'='nano_lifecycle'),'ee200000-0000-0000-0000-000000000004',4,1),'libera reserva de preparação');
select pg_temp.afirma(public.nano_lifecycle_entrada_tecnica('ed000000-0000-0000-0000-000000000001',(select id from public.pipeline_itens where loja_id='ed000000-0000-0000-0000-000000000001' and entrada->>'origem'='nano_lifecycle'),'ee200000-0000-0000-0000-000000000004',4,1)->>'estado'='reserva_invalida','sem reserva não prepara');
select pg_temp.afirma((select estado='entrada' and versao=1 and resultado='{}'::jsonb from public.pipeline_itens where id=(select id from public.pipeline_itens where loja_id='ed000000-0000-0000-0000-000000000001' and entrada->>'origem'='nano_lifecycle')),'preparação não avança pipeline');
reset role;
select pg_temp.afirma(not has_function_privilege('anon','public.nano_lifecycle_entrada_tecnica(uuid,uuid,uuid,bigint,integer)','execute'),'leitura técnica não pública');
rollback;
